import * as T from './vendor/three.js';
// Use the same georeferenced GPU images and streamed tile bindings as the terrain.
// Bright paint, saturated vegetation and deep photographic shadows lose influence.
export function applyRoadImagery(material,layers){
 const previous=material.onBeforeCompile,oldKey=material.customProgramCacheKey.bind(material);
 material.onBeforeCompile=shader=>{previous.call(material,shader);let declarations='varying vec2 vRoadPhotoXZ;\n',fragment='';
  layers.forEach(({texture,bounds,fade=30,textureUniform,extentUniform},i)=>{shader.uniforms['roadPhoto'+i]=textureUniform||{value:texture};shader.uniforms['roadPhotoExtent'+i]=extentUniform||{value:new T.Vector4(bounds.minX,bounds.minZ,bounds.maxX-bounds.minX,bounds.maxZ-bounds.minZ)};declarations+=`uniform sampler2D roadPhoto${i};uniform vec4 roadPhotoExtent${i};\n`;fragment+=`{vec2 photoUV=(vRoadPhotoXZ-roadPhotoExtent${i}.xy)/roadPhotoExtent${i}.zw;float photoEdge=min(min(photoUV.x*roadPhotoExtent${i}.z,(1.-photoUV.x)*roadPhotoExtent${i}.z),min(photoUV.y*roadPhotoExtent${i}.w,(1.-photoUV.y)*roadPhotoExtent${i}.w));float photoWeight=smoothstep(0.,${Number(fade).toFixed(1)},photoEdge);if(photoWeight>0.){vec3 photo=texture2D(roadPhoto${i},vec2(photoUV.x,1.-photoUV.y)).rgb;float lum=dot(photo,vec3(.2126,.7152,.0722));float saturation=max(max(photo.r,photo.g),photo.b)-min(min(photo.r,photo.g),photo.b);float asphaltConfidence=(1.-smoothstep(.07,.18,saturation))*smoothstep(.015,.045,lum)*(1.-smoothstep(.25,.45,lum));vec3 localAsphalt=photo*(clamp(.075+(lum-.08)*.35,.04,.16)/max(lum,.001));diffuseColor.rgb=mix(diffuseColor.rgb,localAsphalt,photoWeight*asphaltConfidence*.70);}}\n`});
  shader.vertexShader='varying vec2 vRoadPhotoXZ;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <project_vertex>','#include <project_vertex>\nvRoadPhotoXZ=(modelMatrix*vec4(transformed,1.)).xz;');shader.fragmentShader=declarations+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <color_fragment>','#include <color_fragment>\n'+fragment);
 };material.customProgramCacheKey=()=>oldKey()+'/local-road-aerial-48/'+layers.length;
}
